package main
import ("context";"log";"net/http";"github.com/jackc/pgx/v5/pgxpool";"github.com/redis/go-redis/v9";"auction/backend/internal/auth";"auction/backend/internal/bid";"auction/backend/internal/config";httpapi "auction/backend/internal/http";"auction/backend/internal/store";"auction/backend/internal/worker";"auction/backend/internal/ws")
func main(){ c,err:=config.Load();if err!=nil{log.Fatal(err)};ctx:=context.Background();db,err:=pgxpool.New(ctx,c.DatabaseURL);if err!=nil{log.Fatal(err)};defer db.Close(); r,err:=redis.ParseURL(c.RedisURL);if err!=nil{log.Fatal(err)};rc:=redis.NewClient(r); defer rc.Close(); as:=auth.New(c.JWTSecret,c.TokenTTL); st:=store.New(db); api:=&httpapi.API{Store:st,Auth:as,Bids:bid.New(rc)}; mux:=api.Routes(); mux.(*http.ServeMux).Handle("/ws",ws.New(as)); go (&worker.Worker{Store:st,Every:c.SettleEvery}).Run(ctx); log.Printf("listening on %s",c.HTTPAddr); log.Fatal(http.ListenAndServe(c.HTTPAddr,mux))}
